reference_solution:
def merge(intervals):
    out = []
    for s, e in sorted(intervals):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

brute_force_solution:
def merge(intervals):
    res = [list(i) for i in intervals]
    changed = True
    while changed:
        changed = False
        for i in range(len(res)):
            for j in range(i + 1, len(res)):
                a, b = res[i], res[j]
                if a[0] <= b[1] and b[0] <= a[1]:
                    res[i] = [min(a[0], b[0]), max(a[1], b[1])]
                    res.pop(j)
                    changed = True
                    break
            if changed:
                break
    return sorted(res)

